package main

import (
    "encoding/csv"
    "encoding/json"
    "flag"
    "fmt"
    "os"
)

func main() {
    input := flag.String("input", "", "input CSV file path")
    filterCol := flag.Int("col", 0, "column index to filter on")
    filterVal := flag.String("value", "", "value to match")
    flag.Parse()

    if *input == "" || *filterVal == "" {
        fmt.Fprintln(os.Stderr, "usage: filter -input file.csv -col 0 -value alice")
        os.Exit(2)
    }

    f, err := os.Open(*input)
    if err != nil {
        fmt.Fprintf(os.Stderr, "open: %v\n", err)
        os.Exit(1)
    }
    defer f.Close()

    r := csv.NewReader(f)
    records, err := r.ReadAll()
    if err != nil {
        fmt.Fprintf(os.Stderr, "read csv: %v\n", err)
        os.Exit(1)
    }

    var result []map[string]string
    if len(records) == 0 {
        return
    }
    headers := records[0]
    for _, row := range records[1:] {
        if len(row) > *filterCol && row[*filterCol] == *filterVal {
            m := make(map[string]string)
            for i, h := range headers {
                if i < len(row) {
                    m[h] = row[i]
                }
            }
            result = append(result, m)
        }
    }

    enc := json.NewEncoder(os.Stdout)
    enc.SetIndent("", "  ")
    enc.Encode(result)
}

package stack

type Stack[T any] struct{ items []T }

func (s *Stack[T]) Push(v T) {
    s.items = append(s.items, v)
}

func (s *Stack[T]) Pop() (T, bool) {
    var zero T
    if len(s.items) == 0 {
        return zero, false
    }
    v := s.items[len(s.items)-1]
    s.items = s.items[:len(s.items)-1]
    return v, true
}

func (s *Stack[T]) Len() int { return len(s.items) }

