package cache

import (
    "sync"
    "time"
)

type entry struct {
    value any
    expiry time.Time
}

type Cache struct {
    mu      sync.RWMutex
    items   map[string]entry
}

func New() *Cache {
    return &Cache{items: make(map[string]entry)}
}

func (c *Cache) Set(key string, val any, ttl time.Duration) {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.items[key] = entry{value: val, expiry: time.Now().Add(ttl)}
}

func (c *Cache) Get(key string) (any, bool) {
    c.mu.RLock()
    e, ok := c.items[key]
    c.mu.RUnlock()
    if !ok {
        return nil, false
    }
    if time.Now().After(e.expiry) {
        c.mu.Lock()
        delete(c.items, key)  // lazy eviction
        c.mu.Unlock()
        return nil, false
    }
    return e.value, true
}

func (c *Cache) StartEvictor(ctx context.Context, interval time.Duration) {
    ticker := time.NewTicker(interval)
    defer ticker.Stop()
    for {
        select {
        case <-ticker.C:
            c.evictExpired()
        case <-ctx.Done():
            return
        }
    }
}

func (c *Cache) evictExpired() {
    now := time.Now()
    c.mu.Lock()
    defer c.mu.Unlock()
    for k, e := range c.items {
        if now.After(e.expiry) {
            delete(c.items, k)
        }
    }
}

package crawler

import (
    "context"
    "net/http"
    "net/url"
    "sync"
    "time"
)

type Crawler struct {
    client    *http.Client
    workers   int
    maxDepth  int
    visited   sync.Map  // URL → struct{}
    rateLimit time.Duration
}

type Result struct {
    URL   string
    Title string
    Depth int
    Err   error
}

func New(workers, maxDepth int, rateLimit time.Duration) *Crawler {
    return &Crawler{
        client:    &http.Client{Timeout: 10 * time.Second},
        workers:   workers,
        maxDepth:  maxDepth,
        rateLimit: rateLimit,
    }
}

func (c *Crawler) Crawl(ctx context.Context, seed string) <-chan Result {
    out := make(chan Result, 100)
    jobs := make(chan job, 100)

    var wg sync.WaitGroup
    for i := 0; i < c.workers; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            c.worker(ctx, jobs, out)
        }()
    }

    go func() {
        defer close(jobs)
        c.enqueue(ctx, jobs, seed, 0)
    }()

    go func() {
        wg.Wait()
        close(out)
    }()

    return out
}

type job struct {
    url   string
    depth int
}

func (c *Crawler) enqueue(ctx context.Context, jobs chan<- job, u string, depth int) {
    if depth > c.maxDepth {
        return
    }
    if _, loaded := c.visited.LoadOrStore(u, struct{}{}); loaded {
        return  // already visited
    }
    select {
    case jobs <- job{url: u, depth: depth}:
    case <-ctx.Done():
    }
}

func (c *Crawler) worker(ctx context.Context, jobs <-chan job, out chan<- Result) {
    for {
        select {
        case j, ok := <-jobs:
            if !ok {
                return
            }
            result, links := c.fetch(ctx, j)
            select {
            case out <- result:
            case <-ctx.Done():
                return
            }
            for _, link := range links {
                c.enqueue(ctx, jobs, link, j.depth+1)
            }
        case <-ctx.Done():
            return
        }
    }
}

func (c *Crawler) fetch(ctx context.Context, j job) (Result, []string) {
    req, err := http.NewRequestWithContext(ctx, "GET", j.url, nil)
    if err != nil {
        return Result{URL: j.url, Depth: j.depth, Err: err}, nil
    }
    resp, err := c.client.Do(req)
    if err != nil {
        return Result{URL: j.url, Depth: j.depth, Err: err}, nil
    }
    defer resp.Body.Close()

    title, links := parseHTML(resp.Body, j.url)
    return Result{URL: j.url, Title: title, Depth: j.depth}, links
}

package main

import (
    "context"
    "log"
    "net/http"
    "os/signal"
    "syscall"
    "time"
)

func main() {
    srv := &http.Server{
        Addr:         ":8080",
        Handler:      mux(),
        ReadTimeout:  5 * time.Second,
        WriteTimeout: 10 * time.Second,
        IdleTimeout:  120 * time.Second,
    }

    ctx, stop := signal.NotifyContext(context.Background(),
        syscall.SIGINT, syscall.SIGTERM)
    defer stop()

    go func() {
        log.Printf("listening on %s", srv.Addr)
        if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
            log.Fatalf("listen: %v", err)
        }
    }()

    <-ctx.Done()
    log.Println("shutdown signal received")

    shutdownCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
    defer cancel()

    if err := srv.Shutdown(shutdownCtx); err != nil {
        log.Printf("forced shutdown: %v", err)
    }
    log.Println("server stopped")
}
